#ifndef STD_SRVS__SRV__EMPTY_HPP_
#define STD_SRVS__SRV__EMPTY_HPP_

// Auto-generated ROS 2-style compatibility header for ROS 1.
// Provides: std_srvs::srv::Empty as a using-alias for the ROS 1
// type std_srvs::Empty. Logic-layer code that declares shared_ptr
// arguments as std::shared_ptr<const T> works on both builds; on ROS 1
// the IF layer converts boost::shared_ptr -> std::shared_ptr via
// sq_ros1_compat::to_std() (no deep copy).

#include "std_srvs/Empty.h"

namespace std_srvs {
namespace srv {
using Empty = ::std_srvs::Empty;
}  // namespace srv
}  // namespace std_srvs

#endif  // STD_SRVS__SRV__EMPTY_HPP_
